  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = vatSummary([issued.value]);
  for (const entry of r) {
    assert.ok(entry.vat >= 0);
  }
});
